"""setgo init — generate a metadata.json scaffold from an arbitrary dataset.

Introspects a data file or directory and emits a ``metadata.json`` that matches
the schema SetGo's assessors and exporters already expect (the same shape REDI's
pipeline writes from ``redi/cli.py``: ``input_file``, ``domain``,
``completed_stages``, ``errors`` plus data-characteristic fields). This lets
``setgo fair/check/publish/card`` operate on datasets that never went through
REDI — SetGo becomes a standalone metadata tool.

If a ``metadata.json`` already exists, ``init`` *enriches* it: it fills in only
the keys that are missing or empty, leaving human-entered values untouched
(unless ``force=True``, which regenerates from scratch).

Heavy/optional dependencies (pyarrow, netCDF4/xarray, h5py, numpy) are imported
lazily and degrade gracefully — a format SetGo can't introspect still yields a
valid scaffold with the fields it could determine.
"""

import csv
import json
import logging
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple

logger = logging.getLogger("setgo.init")

# Data-file extensions worth introspecting, roughly in order of interoperability.
DATA_EXTENSIONS = {
    ".nc", ".nc4", ".hdf5", ".h5", ".zarr", ".parquet",
    ".csv", ".tsv", ".npz", ".npy", ".json", ".jsonl",
    ".cif", ".pdb", ".fasta", ".fastq", ".bp", ".mat",
}

# Files that are never dataset payload.
_SKIP_NAMES = {"metadata.json"}
_SKIP_SUFFIXES = {".md", ".txt", ".log", ".yaml", ".yml"}


def discover_data_files(path: Path) -> List[Path]:
    """Return candidate data files for a path (a single file, or a directory)."""
    if path.is_file():
        return [path]
    files: List[Path] = []
    for child in sorted(path.iterdir()):
        if not child.is_file():
            continue
        if child.name in _SKIP_NAMES or child.name.startswith("."):
            continue
        if child.suffix.lower() in _SKIP_SUFFIXES:
            continue
        if child.suffix.lower() in DATA_EXTENSIONS:
            files.append(child)
    return files


def _introspect_csv(path: Path, delimiter: str = ",") -> Dict[str, Any]:
    out: Dict[str, Any] = {}
    try:
        with open(path, newline="") as f:
            reader = csv.reader(f, delimiter=delimiter)
            header = next(reader, None)
            if header:
                out["feature_columns"] = header
                out["num_columns"] = len(header)
            out["num_rows"] = sum(1 for _ in reader)
    except Exception as e:  # pragma: no cover - defensive
        logger.debug("CSV introspection failed for %s: %s", path, e)
    return out


def _introspect_parquet(path: Path) -> Dict[str, Any]:
    try:
        import pyarrow.parquet as pq
    except Exception:
        return {}
    try:
        pf = pq.ParquetFile(str(path))
        return {
            "feature_columns": list(pf.schema_arrow.names),
            "num_columns": len(pf.schema_arrow.names),
            "num_rows": pf.metadata.num_rows,
        }
    except Exception as e:  # pragma: no cover - defensive
        logger.debug("Parquet introspection failed for %s: %s", path, e)
        return {}


def _introspect_netcdf(path: Path) -> Dict[str, Any]:
    try:
        from netCDF4 import Dataset  # type: ignore
    except Exception:
        return {}
    try:
        ds = Dataset(str(path))
        try:
            variables = [v for v in ds.variables.keys() if v not in ds.dimensions]
            out: Dict[str, Any] = {}
            if variables:
                out["feature_columns"] = variables
                out["num_columns"] = len(variables)
            conventions = getattr(ds, "Conventions", None)
            if conventions:
                out["community_standard"] = str(conventions)
            vocab = sorted({
                str(getattr(ds.variables[v], "standard_name"))
                for v in ds.variables
                if hasattr(ds.variables[v], "standard_name")
            })
            if vocab:
                out["vocabulary_standards"] = vocab
            return out
        finally:
            ds.close()
    except Exception as e:  # pragma: no cover - defensive
        logger.debug("NetCDF introspection failed for %s: %s", path, e)
        return {}


