    def _assess_domain_standards(
        self,
        score: FAIRScore,
        output_dir: Path,
        pipe_meta: Optional[PipelineMetadata],
    ) -> None:
        """Run domain-specific standard validations."""
        if not self._validators:
            return

        # Collect domain-relevant data files; exclude pipeline metadata
        extensions = ["*.nc", "*.nc4", "*.cif", "*.json", "*.hdf5", "*.h5"]
        data_files = [
            f for ext in extensions for f in output_dir.glob(ext)
            if f.name != "metadata.json"
        ]
        if not data_files:
            return

        for data_file in data_files[:3]:  # validate up to 3 files
            for validator in self._validators.values():
                try:
                    result = validator.validate(data_file, None)
                    if result:
                        score.domain_standards[result.standard_name] = result
                except Exception:
