    def _assess_metadata_completeness(
        self, output_dir: Path, pipe_meta: Optional[PipelineMetadata]
    ) -> float:
        """Calculate metadata completeness as a weighted score.

        Title, description, authors, and license are weighted 2× because their
        absence makes a dataset effectively undiscoverable or unusable for reuse.
        """
        if not pipe_meta:
            data_card = output_dir / "DATA_CARD.md"
            if data_card.exists():
                return 0.6
            return 0.0

        # High-priority fields (weight 2 each): max 8 points
        high_priority = [
            bool(pipe_meta.name),
            bool(pipe_meta.description),
            bool(pipe_meta.authors),
            bool(pipe_meta.license),
        ]
        # Normal fields (weight 1 each): max 6 points
        normal_priority = [
            bool(pipe_meta.domain and pipe_meta.domain != "general"),
            pipe_meta.num_rows > 0,
            pipe_meta.num_columns > 0,
            bool(pipe_meta.feature_columns),
            bool(pipe_meta.output_format),
            pipe_meta.train_size > 0,
        ]

        earned = sum(2 for f in high_priority if f) + sum(1 for f in normal_priority if f)
        max_score = 2 * len(high_priority) + len(normal_priority)  # 14
        return earned / max_score

